// Prove real two-physical-D1 routing and pre-provisioned third-shard isolation.
// Synthetic API key is generated by GitHub Actions; no actual TALERA data.
import assert from 'node:assert/strict';
const root='https://talera-d1-stable-router-test-20261108.mark-a39.workers.dev';
const token=process.env.DEMO_TOKEN;
assert.ok(typeof token==='string'&&token.length>=40,'Missing protected synthetic token');
async function call(route,method='GET',data){
 const response=await fetch(root+route,{method,headers:{
  authorization:'Bearer '+token,...(data?{'content-type':'application/json'}:{})
 },body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(25000)});
 return {status:response.status,json:await response.json()};
}
const status=await call('/_demo/status');
assert.equal(status.status,200);
const states=Object.fromEntries(status.json.groups.map(x=>[x.shard_id,x.state]));
assert.equal(states.A,'active','original data shard must remain active');
assert.equal(states.B,'active','second physical data shard must be active');
assert.equal(states.C,'disabled','future third data shard must NOT accept accounts');
const pinned=await call('/_demo/provision','POST',{accountId:'demo-gh-smoke-20261108'});
assert.equal(pinned.status,200);
assert.equal(pinned.json.shard,'A','old account must not be moved after B is enabled');
let accounts={A:null,B:null},firstPersistedB=null;
for(let i=0;i<80;i++){
 const id='demo-multishard-test-'+i;
 const provisioned=await call('/_demo/provision','POST',{accountId:id});
 assert.equal(provisioned.status,200);
 assert.ok(['A','B'].includes(provisioned.json.shard),'C must be inactive for new assignments');
 if(!accounts[provisioned.json.shard])accounts[provisioned.json.shard]=id;
 if(provisioned.json.shard==='B'&&firstPersistedB===null)firstPersistedB=id;
 if(accounts.A&&accounts.B)break;
}
assert.ok(accounts.A&&accounts.B,'Synthetic new accounts must reach both physical data shards');
for(const [shard,id] of Object.entries(accounts)){
 const storyId='story-growth-'+shard.toLowerCase();
 const original='Synthetic record for physical D1 '+shard+'; no real media';
 const written=await call('/_demo/story','POST',{accountId:id,storyId,text:original});
 assert.equal(written.status,200);
 assert.equal(written.json.storedIn,shard);
 const read=await call('/_demo/story?accountId='+id+'&storyId='+storyId);
 assert.equal(read.status,200);
 assert.equal(read.json.shard,shard);
 assert.equal(read.json.text,original);
 const pinnedLater=await call('/_demo/provision','POST',{accountId:id});
 assert.equal(pinnedLater.status,200);
 assert.equal(pinnedLater.json.shard,shard);
 assert.equal(pinnedLater.json.newAssignment,false);
}
// Cross-account queries do not silently return another tenant's story.
const wrongOwner=await call('/_demo/story?accountId='+accounts.A+'&storyId=story-growth-b');
assert.equal(wrongOwner.status,404);
const publicRequest=await fetch(root+'/_demo/status');
assert.equal(publicRequest.status,401);
console.log('REAL_MULTISHARD_TEST_PASS',JSON.stringify({
 active:['A','B'],standby:['C'],oldAccountStayed:'A',
 isolatedPhysicalShardRoundtrips:2,oldAndNewAssignmentsPersisted:true,
 crossAccountReadBlocked:true,firstPhysicalBAccount:firstPersistedB
}));
